INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7404449, 1165843, 25024, '<td valign="top">*Hello from Sid and the Critique Club*<br/> <br/>An interesting image that meets the challenge.<br/> <br/>This is an appealing image in all sorts of ways but the detail is what holds your interest well, the challenge of your title too I reckon! It is a lovely building with some lovely detail and lovely tones all very appealing. I don''t agree with your commenter about it being slightly crooked I think what they are seeing is a very slight tendency towards converging verticals from your shooting position below. Hah, I see it yes, the top is askew he were right you know! Having said that the bottom is not, ok I give up!<br/> <br/>Although it is a well executed image I think where it fails in terms of the challenge is that the DOF from use of f8 is not obvious and this is perhaps why it scored lower. I think for the purpose of this challenge you need to demonstrate the f8 aperture through a selective DOF and perspective. This could quite easily have been taken at f4 for example but because it is all on the same focal plane you wouldn''t know the difference. <br/> <br/>Thanks for your submission, Sid</td>', '*Hello from Sid and the Critique Club* An interesting image that meets the challenge. This is an appealing image in all sorts of ways but the detail is what holds your interest well, the challenge of your title too I reckon! It is a lovely building with some lovely detail and lovely tones all very appealing. I don''t agree with your commenter about it being slightly crooked I think what they are seeing is a very slight tendency towards converging verticals from your shooting position below. Hah, I see it yes, the top is askew he were right you know! Having said that the bottom is not, ok I give up! Although it is a well executed image I think where it fails in terms of the challenge is that the DOF from use of f8 is not obvious and this is perhaps why it scored lower. I think for the purpose of this challenge you need to demonstrate the f8 aperture through a selective DOF and perspective. This could quite easily have been taken at f4 for example but because it is all on the same focal plane you wouldn''t know the difference.  Thanks for your submission, Sid', '2015-09-14 06:09:31.000000', NULL, 0),
